create extension if not exists pgcrypto;
create extension if not exists unaccent;

create type public.user_role as enum ('user','advisor','editor','admin');
create type public.advisor_status as enum ('draft','published','suspended','archived');
create type public.moderation_status as enum ('pending','approved','rejected');

create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text, role public.user_role not null default 'user', avatar_url text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.firms (id uuid primary key default gen_random_uuid(), name text not null, slug text not null unique, website text, description text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.advisors (id uuid primary key default gen_random_uuid(), first_name text not null, middle_name text, last_name text not null, display_name text not null, slug text not null unique, profile_photo_url text, professional_title text, advisor_type text, firm_id uuid references public.firms(id) on delete set null, email text, phone text, website text, linkedin_url text, address text, city text, state text, zip_code text, country text default 'United States', latitude numeric(9,6), longitude numeric(9,6), short_bio text, biography text, years_experience integer check(years_experience>=0), crd_number text, sec_number text, license_number text, assets_under_management numeric(16,2), minimum_investment numeric(16,2), average_rating numeric(3,2) not null default 0, review_count integer not null default 0, accepting_new_clients boolean not null default false, virtual_consultation boolean not null default false, fiduciary boolean not null default false, verified boolean not null default false, featured boolean not null default false, is_demo boolean not null default false, status public.advisor_status not null default 'draft', disclosures text, external_verification_url text, seo_title text, seo_description text, profile_views bigint not null default 0, search_document tsvector generated always as (to_tsvector('english',coalesce(display_name,'')||' '||coalesce(city,'')||' '||coalesce(state,'')||' '||coalesce(zip_code,'')||' '||coalesce(professional_title,'')||' '||coalesce(short_bio,''))) stored, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), created_by uuid references public.profiles(id));
create table public.specialties (id uuid primary key default gen_random_uuid(), name text not null, slug text not null unique, description text, is_public boolean not null default true, created_at timestamptz not null default now());
create table public.advisor_specialties (advisor_id uuid references public.advisors(id) on delete cascade, specialty_id uuid references public.specialties(id) on delete cascade, primary key(advisor_id,specialty_id));
create table public.certifications (id uuid primary key default gen_random_uuid(), name text not null, acronym text, slug text not null unique, issuing_organization text, description text, is_public boolean not null default true);
create table public.advisor_certifications (advisor_id uuid references public.advisors(id) on delete cascade, certification_id uuid references public.certifications(id) on delete cascade, credential_number text, verified_at timestamptz, expires_at date, primary key(advisor_id,certification_id));
create table public.services (id uuid primary key default gen_random_uuid(), name text not null, slug text not null unique, description text);
create table public.advisor_services (advisor_id uuid references public.advisors(id) on delete cascade, service_id uuid references public.services(id) on delete cascade, primary key(advisor_id,service_id));
create table public.languages (id uuid primary key default gen_random_uuid(), name text not null unique, code text);
create table public.advisor_languages (advisor_id uuid references public.advisors(id) on delete cascade, language_id uuid references public.languages(id) on delete cascade, primary key(advisor_id,language_id));
create table public.fee_structures (id uuid primary key default gen_random_uuid(), name text not null, slug text not null unique, description text);
create table public.advisor_fee_structures (advisor_id uuid references public.advisors(id) on delete cascade, fee_structure_id uuid references public.fee_structures(id) on delete cascade, primary key(advisor_id,fee_structure_id));
create table public.education (id uuid primary key default gen_random_uuid(), advisor_id uuid not null references public.advisors(id) on delete cascade, institution text not null, degree text, field_of_study text, graduation_year integer, sort_order integer default 0);
create table public.professional_experience (id uuid primary key default gen_random_uuid(), advisor_id uuid not null references public.advisors(id) on delete cascade, organization text not null, title text not null, start_date date, end_date date, is_current boolean not null default false, description text, sort_order integer default 0);
create table public.reviews (id uuid primary key default gen_random_uuid(), advisor_id uuid not null references public.advisors(id) on delete cascade, user_id uuid references public.profiles(id) on delete set null, reviewer_name text not null, rating integer not null check(rating between 1 and 5), review_title text, review_text text not null, relationship_type text, verification_status text default 'unverified', moderation_status public.moderation_status not null default 'pending', created_at timestamptz not null default now());
create table public.favorites (user_id uuid references public.profiles(id) on delete cascade, advisor_id uuid references public.advisors(id) on delete cascade, created_at timestamptz not null default now(), primary key(user_id,advisor_id));
create table public.advisor_inquiries (id uuid primary key default gen_random_uuid(), advisor_id uuid not null references public.advisors(id) on delete cascade, user_id uuid references public.profiles(id) on delete set null, name text not null, email text not null, phone text, preferred_contact_method text, financial_goal text, investable_assets_range text, message text not null, consent boolean not null, status text not null default 'new', created_at timestamptz not null default now());
create table public.profile_claims (id uuid primary key default gen_random_uuid(), advisor_id uuid not null references public.advisors(id) on delete cascade, user_id uuid references public.profiles(id) on delete set null, full_name text not null, work_email text not null, phone text, firm text, position text, message text, document_url text, status public.moderation_status not null default 'pending', created_at timestamptz not null default now());
create table public.article_categories (id uuid primary key default gen_random_uuid(), name text not null, slug text not null unique, description text);
create table public.articles (id uuid primary key default gen_random_uuid(), title text not null, slug text not null unique, excerpt text, content text, featured_image_url text, author_id uuid references public.profiles(id), category_id uuid references public.article_categories(id), published_at timestamptz, seo_title text, seo_description text, status public.advisor_status not null default 'draft', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.locations (id uuid primary key default gen_random_uuid(), city text not null, state text not null, state_slug text not null, city_slug text not null, latitude numeric(9,6), longitude numeric(9,6), unique(state_slug,city_slug));
create table public.admin_activity (id uuid primary key default gen_random_uuid(), admin_id uuid references public.profiles(id), action text not null, entity_type text, entity_id uuid, metadata jsonb default '{}', created_at timestamptz not null default now());
create table public.advisor_verifications (id uuid primary key default gen_random_uuid(), advisor_id uuid not null references public.advisors(id) on delete cascade, verified_by uuid references public.profiles(id), verification_type text not null, source_url text, notes text, verified_at timestamptz not null default now(), expires_at timestamptz);
create table public.analytics_events (id bigint generated always as identity primary key, event_name text not null check(event_name in ('advisor_search','advisor_view','advisor_contact','advisor_save','advisor_compare','filter_used','profile_claim','review_submission')), advisor_id uuid references public.advisors(id) on delete set null, user_id uuid references public.profiles(id) on delete set null, session_id text, metadata jsonb default '{}', created_at timestamptz not null default now());

create index advisors_status_idx on public.advisors(status); create index advisors_location_idx on public.advisors(state,city,zip_code); create index advisors_flags_idx on public.advisors(verified,featured,accepting_new_clients); create index advisors_search_idx on public.advisors using gin(search_document); create index reviews_advisor_status_idx on public.reviews(advisor_id,moderation_status); create index events_name_created_idx on public.analytics_events(event_name,created_at desc);
create or replace function public.set_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now(); return new; end $$;
create trigger advisors_updated before update on public.advisors for each row execute function public.set_updated_at(); create trigger profiles_updated before update on public.profiles for each row execute function public.set_updated_at(); create trigger firms_updated before update on public.firms for each row execute function public.set_updated_at(); create trigger articles_updated before update on public.articles for each row execute function public.set_updated_at();
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from profiles where id=auth.uid() and role='admin') $$;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into profiles(id,full_name) values(new.id,new.raw_user_meta_data->>'full_name'); return new; end $$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
create or replace function public.refresh_advisor_rating() returns trigger language plpgsql security definer set search_path=public as $$ declare aid uuid; begin aid=coalesce(new.advisor_id,old.advisor_id); update advisors set average_rating=coalesce((select avg(rating)::numeric(3,2) from reviews where advisor_id=aid and moderation_status='approved'),0),review_count=(select count(*) from reviews where advisor_id=aid and moderation_status='approved') where id=aid; return coalesce(new,old); end $$;
create trigger reviews_rating_refresh after insert or update or delete on public.reviews for each row execute function public.refresh_advisor_rating();

alter table public.profiles enable row level security; alter table public.advisors enable row level security; alter table public.firms enable row level security; alter table public.specialties enable row level security; alter table public.advisor_specialties enable row level security; alter table public.certifications enable row level security; alter table public.advisor_certifications enable row level security; alter table public.services enable row level security; alter table public.advisor_services enable row level security; alter table public.languages enable row level security; alter table public.advisor_languages enable row level security; alter table public.fee_structures enable row level security; alter table public.advisor_fee_structures enable row level security; alter table public.education enable row level security; alter table public.professional_experience enable row level security; alter table public.reviews enable row level security; alter table public.favorites enable row level security; alter table public.advisor_inquiries enable row level security; alter table public.profile_claims enable row level security; alter table public.article_categories enable row level security; alter table public.articles enable row level security; alter table public.locations enable row level security; alter table public.admin_activity enable row level security; alter table public.advisor_verifications enable row level security; alter table public.analytics_events enable row level security;
create policy "public published advisors" on public.advisors for select using(status='published' or public.is_admin()); create policy "admins manage advisors" on public.advisors for all using(public.is_admin()) with check(public.is_admin());
create policy "public firms" on public.firms for select using(true); create policy "admins manage firms" on public.firms for all using(public.is_admin()) with check(public.is_admin());
create policy "public specialties" on public.specialties for select using(is_public or public.is_admin()); create policy "public certifications" on public.certifications for select using(is_public or public.is_admin());
create policy "public taxonomy" on public.services for select using(true); create policy "public languages" on public.languages for select using(true); create policy "public fees" on public.fee_structures for select using(true); create policy "public locations" on public.locations for select using(true);
create policy "public join specialties" on public.advisor_specialties for select using(exists(select 1 from advisors a where a.id=advisor_id and a.status='published')); create policy "public join certifications" on public.advisor_certifications for select using(exists(select 1 from advisors a where a.id=advisor_id and a.status='published')); create policy "public join services" on public.advisor_services for select using(exists(select 1 from advisors a where a.id=advisor_id and a.status='published')); create policy "public join languages" on public.advisor_languages for select using(exists(select 1 from advisors a where a.id=advisor_id and a.status='published')); create policy "public join fees" on public.advisor_fee_structures for select using(exists(select 1 from advisors a where a.id=advisor_id and a.status='published'));
create policy "public approved reviews" on public.reviews for select using(moderation_status='approved' or public.is_admin()); create policy "users submit reviews" on public.reviews for insert to authenticated with check(user_id=auth.uid()); create policy "admins manage reviews" on public.reviews for all using(public.is_admin()) with check(public.is_admin());
create policy "own favorites" on public.favorites for all to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid()); create policy "submit inquiries" on public.advisor_inquiries for insert to anon,authenticated with check(consent=true); create policy "own inquiries" on public.advisor_inquiries for select to authenticated using(user_id=auth.uid() or public.is_admin()); create policy "submit claims" on public.profile_claims for insert to authenticated with check(user_id=auth.uid()); create policy "own claims" on public.profile_claims for select to authenticated using(user_id=auth.uid() or public.is_admin());
create policy "published articles" on public.articles for select using(status='published' or public.is_admin()); create policy "public article categories" on public.article_categories for select using(true); create policy "admins all profiles" on public.profiles for all using(public.is_admin()) with check(public.is_admin()); create policy "own profile" on public.profiles for select using(id=auth.uid()); create policy "own profile update" on public.profiles for update using(id=auth.uid()) with check(id=auth.uid());
create policy "admins activity" on public.admin_activity for all using(public.is_admin()) with check(public.is_admin()); create policy "admins verifications" on public.advisor_verifications for all using(public.is_admin()) with check(public.is_admin()); create policy "public verified records" on public.advisor_verifications for select using(true); create policy "insert analytics" on public.analytics_events for insert to anon,authenticated with check(true); create policy "admins analytics" on public.analytics_events for select using(public.is_admin());

create view public.advisors_public with (security_invoker=true) as select a.*,f.name as firm_name,array(select s.name from advisor_specialties x join specialties s on s.id=x.specialty_id where x.advisor_id=a.id) specialties,array(select coalesce(c.acronym,c.name) from advisor_certifications x join certifications c on c.id=x.certification_id where x.advisor_id=a.id) credentials,array(select fs.name from advisor_fee_structures x join fee_structures fs on fs.id=x.fee_structure_id where x.advisor_id=a.id) fee_structures,array(select l.name from advisor_languages x join languages l on l.id=x.language_id where x.advisor_id=a.id) languages from advisors a left join firms f on f.id=a.firm_id where a.status='published';

insert into storage.buckets(id,name,public) values ('advisor-photos','advisor-photos',true),('article-images','article-images',true),('documents','documents',false) on conflict do nothing;
create policy "public advisor photos" on storage.objects for select using(bucket_id='advisor-photos'); create policy "admins upload media" on storage.objects for insert to authenticated with check(public.is_admin() and bucket_id in ('advisor-photos','article-images','documents')); create policy "admins manage media" on storage.objects for all to authenticated using(public.is_admin()) with check(public.is_admin());
